// n8n Function node — Structure contact data from SerpAPI google_ai_mode results
// Rule: in search_parameters.q → before first comma = name, after = headline

/** ---------------- helpers ---------------- */
const A = v => Array.isArray(v) ? v : (v == null ? [] : [v]);
const uniq = arr => {
  const s = new Set(), out = [];
  for (const x of arr || []) {
    const t = String(x ?? '').trim();
    if (!t || s.has(t)) continue;
    s.add(t); out.push(t);
  }
  return out;
};
const normEmail = e => {
  const v = String(e||'').trim();
  return /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i.test(v) ? v.toLowerCase() : null;
};
function extractEmails(text) {
  if (!text) return [];
  const m = String(text).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig) || [];
  return uniq(m.map(normEmail).filter(Boolean));
}
function extractPhones(text) {
  if (!text) return [];
  const raw = String(text).match(/\+?\d[\d()\-\s]{6,}/g) || [];
  return uniq(
    raw.map(t => t.replace(/[^\d+]/g, ''))
       .filter(t => /^\+?\d{7,15}$/.test(t) || /^\d{10,15}$/.test(t))
       .map(t => (t.startsWith('+') ? t : (t.length >= 10 ? '+' + t : null)))
       .filter(Boolean)
  );
}
function linksFromReferences(refs) {
  const out = [];
  for (const r of refs || []) {
    if (r?.link) out.push(r.link);
    const sn = String(r?.snippet || '');
    const found = sn.match(/https?:\/\/[^\s)]+/g) || [];
    out.push(...found);
  }
  return uniq(out);
}
function addressFromBlocks(blocks) {
  const locKey = /(Address:|Location:|Road|Campus|Ghaziabad|Indore|Nagpur|Gorakhpur|Jhalawar|Karnataka|India|\bPIN:|\bUttar\b|\bRajasthan\b)/i;
  for (const b of blocks || []) {
    if (b?.type === 'list' && Array.isArray(b.list)) {
      for (const li of b.list) {
        const t = String(li?.snippet || '').trim();
        if (locKey.test(t)) return t.replace(/^(Address:|Location:)\s*/i, '').trim();
      }
    } else if (b?.type === 'paragraph') {
      const t = String(b?.snippet || '').trim();
      if (locKey.test(t)) return t.replace(/^(Address:|Location:)\s*/i, '').trim();
    }
  }
  return null;
}
function emailsPhonesFromBlocks(blocks) {
  const emails = [], phones = [];
  for (const b of blocks || []) {
    if (b?.type === 'list' && Array.isArray(b.list)) {
      for (const li of b.list) {
        const s = String(li?.snippet || '');
        emails.push(...extractEmails(s));
        phones.push(...extractPhones(s));
      }
    } else if (b?.type === 'paragraph') {
      const s = String(b?.snippet || '');
      emails.push(...extractEmails(s));
      phones.push(...extractPhones(s));
    }
  }
  return { emails: uniq(emails), phones: uniq(phones) };
}
function buildAbout(blocks) {
  const paras = (blocks || [])
    .filter(b => b?.type === 'paragraph')
    .map(b => String(b.snippet || '').trim())
    .filter(Boolean);
  return paras.slice(0, 2).join(' ') || null;
}

/** ----------- parse name/headline from q with comma rule ----------- */
function parseFromQ(qRaw) {
  if (!qRaw) return { name: null, headline: null };
  // keep "Contact Details" in q, but strip it before parsing name/headline
  let q = String(qRaw).trim().replace(/^\s*Contact\s+Details\s*/i, '').trim();

  // Fix glued tokens like "Institute , Training" spacing
  q = q.replace(/\s*,\s*/g, ', ').replace(/\s{2,}/g, ' ').trim();

  // Primary rule: split on first comma
  const firstComma = q.indexOf(',');
  if (firstComma !== -1) {
    const name = q.slice(0, firstComma).trim() || null;
    const headline = q.slice(firstComma + 1).trim() || null;
    return { name, headline };
  }

  // Fallback (no comma): try simple "role at org" split
  const atIdx = q.toLowerCase().indexOf(' at ');
  if (atIdx > 0) {
    return {
      name: q.slice(0, atIdx).trim() || null,
      headline: q.slice(atIdx + 1).trim() || null
    };
  }

  // Final fallback: whole string becomes name
  return { name: q, headline: null };
}

/** ---------------- main ---------------- */
const out = [];

for (const it of (Array.isArray(items) ? items : [items])) {
  const payload = it?.json ?? it;

  const q       = payload?.search_parameters?.q || null;
  const blocks  = payload?.text_blocks || [];
  const refs    = payload?.references || [];

  const { name, headline } = parseFromQ(q);
  const { emails, phones } = emailsPhonesFromBlocks(blocks);
  const about   = buildAbout(blocks);
  const address = addressFromBlocks(blocks);
  const sources = linksFromReferences(refs);

  const meta = {
    query: q,
    engine: payload?.search_parameters?.engine || null,
    id: payload?.search_metadata?.id || null,
    created_at: payload?.search_metadata?.created_at || null,
  };

  out.push({
    json: { name, headline, emails, phones, about, address, sources, meta }
  });
}

return out.length ? out : items;

// In a Code node
const urls = items.map(item => item.json.link)  // Changed from 'url' to 'link'
  .filter(url => !url.includes('/company/'));

// Return array of items instead of single object
return urls.map(url => ({ profileUrls: [url] }));

const startIndexes = [];
for (let i = 10; i <=200; i += 10){
  startIndexes.push(i);
}
return {startIndexes}

// n8n Function node
// Input: SerpAPI response (item.json) from previous HTTP Request node
// Output: flattened, structured items for Google organic LinkedIn results

function parseFollowers(text) {
  if (!text) return null;
  const m = String(text).match(/([\d.,]+)\s*\+?\s*(k|m)?\s*followers/i);
  if (!m) return null;
  let n = parseFloat(m[1].replace(/,/g, ''));
  const unit = (m[2] || '').toLowerCase();
  if (unit === 'k') n *= 1_000;
  if (unit === 'm') n *= 1_000_000;
  return Math.round(n);
}

function roleGuess(text) {
  const t = String(text || '').toLowerCase();
  if (/(head of department|[^a-z]hod[^a-z])/i.test(t)) return 'HOD';
  if (/\bdean\b/.test(t)) return 'Dean';
  if (/\bdirector\b/.test(t)) return 'Director';
  if (/\bprincipal\b/.test(t)) return 'Principal';
  if (/\bassistant professor\b/.test(t)) return 'Assistant Professor';
  if (/\bassociate professor\b/.test(t)) return 'Associate Professor';
  if (/\bprofessor\b/.test(t)) return 'Professor';
  if (/\blecturer\b/.test(t)) return 'Lecturer';
  return null;
}

function splitTitle(title) {
  if (!title) return { name: null, headline: null };
  const byDash = String(title).split(' - ');
  if (byDash.length > 1) {
    return {
      name: byDash[0].trim(),
      headline: byDash.slice(1).join(' - ').trim() || null,
    };
  }
  const byPipe = String(title).split(' | ');
  if (byPipe.length > 1) {
    return {
      name: byPipe[0].trim(),
      headline: byPipe.slice(1).join(' | ').trim() || null,
    };
  }
  return { name: null, headline: String(title).trim() };
}

function pickLocationAndOrg(extensions = []) {
  if (!Array.isArray(extensions)) return { location_hint: null, org_hint: null };
  const locIdx = extensions.findIndex(s =>
    /India|Delhi|Mumbai|Bengaluru|Bangalore|Chennai|Hyderabad|Kolkata|Pune|Ahmedabad|Uttar|Maharashtra|Tamil Nadu|Karnataka|Gujarat|Punjab|Rajasthan|Madhya Pradesh|Uttarakhand|Chhattisgarh|Andhra|Telangana|Kerala|Assam|Bihar|Jharkhand|Odisha|Goa|Haryana|Jammu|Kashmir|Himachal|Tripura|Manipur|Mizoram|Meghalaya|Nagaland|Sikkim|Chandigarh|Puducherry/i.test(s || '')
  );
  const location_hint = locIdx >= 0 ? extensions[locIdx] : null;
  const org_hint = extensions.find((s, i) => i !== locIdx) || null;
  return { location_hint, org_hint };
}

function hostInfo(link) {
  try {
    const h = new URL(link).hostname || null;
    const tld = h ? h.split('.').slice(-1)[0] : null;
    return { hostname: h, tld_country: tld };
  } catch {
    return { hostname: null, tld_country: null };
  }
}

const out = [];

for (const item of items) {
  // Support both: raw object or wrapped in an array (like your pasted sample)
  const payload = Array.isArray(item.json) ? item.json[0] : item.json;
  if (!payload || !payload.organic_results) continue;

  const q = payload.search_parameters?.q || null;
  const nextPage = payload.serpapi_pagination?.next || null;
  const searchId = payload.search_metadata?.id || null;

  for (const r of payload.organic_results) {
    const title = r.title || null;
    const { name, headline } = splitTitle(title);
    const link = r.link || null;
    const snippet = r.snippet || null;
    const followers_est = parseFollowers(r.displayed_link);
    const { location_hint, org_hint } = pickLocationAndOrg(r.rich_snippet?.top?.extensions || []);
    const { hostname, tld_country } = hostInfo(link);
    const role = roleGuess(`${title} ${snippet}`);

    const is_india =
      /(^|[\s,])India([\s,]|$)/i.test(`${location_hint || ''} ${snippet || ''}`) ||
      /\.in$/.test(hostname || '') ||
      tld_country === 'in';

    out.push({
      json: {
        // SERP context
        search_id: searchId,
        query: q,
        position: r.position ?? null,
        page_next: nextPage || null,

        // Lead fields
        name,
        headline,
        role_guess: role,
        link,
        linkedin_host: hostname,
        tld_country,
        is_india,

        // Extra context
        followers_est,
        snippet,
        location_hint,
        org_hint,
        source: r.source || null,
        displayed_link: r.displayed_link || null,
        favicon: r.favicon || null
      }
    });
  }
}

return out.length ? out : items;
